import{_ as i,o as e,c as r,a2 as n,j as a,a as s}from"./chunks/framework.DxqK4cCD.js";const k=JSON.parse('{"title":"Neonatal Hypoxic-ischaemic Encephalopathy Classification from the EEG and HRV Signals Using a Conformer based Masked Autoencoder","description":"提出MAEConformer，结合卷积和自注意力机制，通过掩码自编码从无标签EEG/HRV中学习通用表示，显著提升新生儿HIE分类性能。","frontmatter":{"title":"Neonatal Hypoxic-ischaemic Encephalopathy Classification from the EEG and HRV Signals Using a Conformer based Masked Autoencoder","description":"提出MAEConformer，结合卷积和自注意力机制，通过掩码自编码从无标签EEG/HRV中学习通用表示，显著提升新生儿HIE分类性能。","date":"2026-07-28","arxivId":"2607.23554","domain":"机器学习 · 人工智能 · 信号处理","level":"进阶","tags":["掩码自编码器","Conformer","新生儿HIE","脑电图","心率变异性"],"originalUrl":"https://arxiv.org/abs/2607.23554","sourceUrl":"https://github.com/vsvnakers/paper-daily/blob/master/essay_read/2026-07-28/2607.23554.md"},"headers":[],"relativePath":"papers/daily/2026-07-28/2607.23554.md","filePath":"papers/daily/2026-07-28/2607.23554.md","lastUpdated":1786541753000}'),l={name:"papers/daily/2026-07-28/2607.23554.md"};function o(h,t,E,p,d,g){return e(),r("div",null,[...t[0]||(t[0]=[n("",15),a("ul",null,[a("li",null,[a("strong",null,"MAEConformer架构"),s("：编码器（Encoder）采用Conformer块，每个块包含两个前馈模块（Feed-Forward Module）、一个卷积模块（Convolution Module）和一个多头自注意力模块（Multi-Head Self-Attention Module），按“前馈-自注意力-卷积-前馈”顺序排列。解码器（Decoder）为轻量级Transformer，仅由自注意力层组成。输入信号被分割成不重叠的片段（Patches），随机掩码大部分片段（如75%），仅保留可见片段送入编码器。解码器接收编码器输出的可见片段表示和可学习的掩码令牌（Mask Tokens），重建原始信号。")]),a("li",null,[a("strong",null,"多分辨率短时傅里叶变换损失"),s("：传统MAE仅使用时域均方误差（Mean Squared Error, MSE）损失。本文额外引入MR-STFT损失，计算重建信号与原始信号在不同窗长（如256、512、1024个样本点）下的STFT幅度谱之间的L1距离。这迫使模型同时学习时域波形和多个时间尺度下的频域特征。总损失为 $\\mathcal{L}"),a("em",{MSE:""},"{total} = \\mathcal{L}"),s(" + \\lambda \\cdot \\mathcal{L}_{MR-STFT}$，其中 $\\lambda$ 为平衡系数。")]),a("li",null,[a("strong",null,"预训练与微调策略"),s("：在EEG和HRV上分别预训练独立的MAEConformer模型。EEG模型使用6030小时无标签数据，HRV模型使用4868小时数据。预训练后，移除解码器，将编码器输出的[CLS]令牌（或所有令牌的均值池化）作为特征表示，接一个线性分类头进行下游HIE分类微调。微调时采用冻结编码器+训练分类头（Linear Probing）或全参数微调（Full Fine-tuning）两种策略。")]),a("li",null,[a("strong",null,"数据预处理"),s("：EEG信号经过带通滤波（0.5-30Hz）、降采样、标准化处理。HRV信号从心电图（Electrocardiogram, ECG）中提取R-R间期序列，并进行异常值校正和重采样。输入序列长度固定为 $T$ 个时间点，分割成 $N$ 个不重叠的片段，每个片段长度为 $P$。")]),a("li",null,[a("strong",null,"掩码策略"),s("：采用随机掩码，以片段为单位进行掩码。掩码比例设为75%，这是图像MAE中的常用设置，经实验验证在生理信号上也有效。")])],-1),n("",6),a("ol",null,[a("li",null,[a("p",null,[a("strong",null,"总损失函数"),s("： $$\\mathcal{L}"),a("em",{MSE:""},"{total} = \\mathcal{L}"),s(" + \\lambda \\cdot \\mathcal{L}"),a("em",{MSE:""},"{MR-STFT}$$ 其中 $\\mathcal{L}"),s("$ 是重建信号与原始信号在时域上的均方误差，$\\mathcal{L}_{MR-STFT}$ 是多分辨率STFT幅度谱的L1损失，$\\lambda$ 是平衡系数（实验中设为1）。")])]),a("li",null,[a("p",null,[a("strong",null,"多分辨率STFT损失"),s("： $$\\mathcal{L}"),a("em",{m:"1"},"{MR-STFT} = \\frac{1}{M} \\sum"),s("^{M} \\left| \\text{STFT}"),a("em",{w_m:""},"{w_m}(x) - \\text{STFT}"),s("(\\hat{x}) \\right|_1$$ 其中 $M$ 是窗函数数量，$w_m$ 是第 $m$ 个窗长（如256、512、1024），$x$ 和 $\\hat{x}$ 分别是原始信号和重建信号，$|\\cdot|_1$ 表示L1范数。")])]),a("li",null,[a("p",null,[a("strong",null,"Conformer块内部结构"),s("（简化表示）： $$\\text{ConformerBlock}(x) = x + \\frac{1}{2} \\text{FFN}(x) + \\text{MHSA}(x) + \\text{Conv}(x) + \\frac{1}{2} \\text{FFN}(x)$$ 其中FFN为前馈网络，MHSA为多头自注意力，Conv为卷积模块。实际顺序为：FFN -> MHSA -> Conv -> FFN，每个子层后均有残差连接和层归一化。")])])],-1),n("",39)])])}const m=i(l,[["render",o]]);export{k as __pageData,m as default};
